import json

REQUIRED = {'supplier', 'invoice_date', 'currency', 'total'}

def validate_extraction(raw):
    data = json.loads(raw)
    missing = REQUIRED - data.keys()
    if missing:
        return {'status': 'REVIEW', 'missing': sorted(missing)}
    if not isinstance(data['total'], (int, float)):
        return {'status': 'REVIEW', 'reason': 'total must be numeric'}
    return {'status': 'ACCEPT', 'data': data}
